{"code":"        if not self.applied_versions:
            return sorted(
                self.available_migrations,
                key=lambda m: int(m["version"]),
            )

        max_applied = max(self.applied_versions, key=lambda v: int(v))
        pending = [
            m
            for m in self.available_migrations
            if int(m["version"]) > int(max_applied)
        ]
        return sorted(pending, key=lambda m: int(m["version"]))","comments":"Switched migration version comparisons and sorting to numeric order to prevent lexicographic bugs while keeping behavior otherwise unchanged."}
